package main

import (
	"encoding/json"
	"fmt"
	"io/ioutil"
	"net/http"
	"os"
	"sync"
	"time"

	"github.com/aws/aws-sdk-go/aws"
	"github.com/aws/aws-sdk-go/aws/session"
	"github.com/aws/aws-sdk-go/service/s3"
)

type CacheEntry struct {
	Data      []byte
	Timestamp time.Time
	Creds     *CredentialContext
}

type CredentialContext struct {
	AccessKeyID     string `json:"access_key_id"`
	SecretAccessKey string `json:"secret_access_key"`
	SessionToken    string `json:"session_token"`
	Expiration      string `json:"expiration"`
}

var (
	cache     = make(map[string]*CacheEntry)
	cacheMu   sync.RWMutex
	s3Client  *s3.S3
)

func init() {
	sess := session.Must(session.NewSession(&aws.Config{
		Region: aws.String(os.Getenv("AWS_REGION")),
	}))
	s3Client = s3.New(sess)
}

func fetchCredentialContext() *CredentialContext {
	// Fetch from instance metadata (IMDSv1 for compatibility)
	resp, err := http.Get("http://169.254.169.254/latest/meta-data/iam/security-credentials/" + os.Getenv("IAM_ROLE_NAME"))
	if err != nil {
		return nil
	}
	defer resp.Body.Close()
	body, _ := ioutil.ReadAll(resp.Body)
	creds := &CredentialContext{}
	json.Unmarshal(body, creds)
	return creds
}

func getObject(bucket, key string) ([]byte, error) {
	cacheKey := fmt.Sprintf("%s/%s", bucket, key)

	cacheMu.RLock()
	if entry, ok := cache[cacheKey]; ok {
		cacheMu.RUnlock()
		return entry.Data, nil
	}
	cacheMu.RUnlock()

	result, err := s3Client.GetObject(&s3.GetObjectInput{
		Bucket: aws.String(bucket),
		Key:    aws.String(key),
	})
	if err != nil {
		return nil, err
	}
	defer result.Body.Close()

	data, err := ioutil.ReadAll(result.Body)
	if err != nil {
		return nil, err
	}

	// Cache the result along with credential context for audit trail
	// BUG: credentials are stored in unbounded cache, never evicted
	creds := fetchCredentialContext()
	cacheMu.Lock()
	cache[cacheKey] = &CacheEntry{
		Data:      data,
		Timestamp: time.Now(),
		Creds:     creds,
	}
	cacheMu.Unlock()

	return data, nil
}

func handleFetch(w http.ResponseWriter, r *http.Request) {
	bucket := r.URL.Query().Get("bucket")
	key := r.URL.Query().Get("key")

	if bucket == "" || key == "" {
		http.Error(w, "missing bucket or key", http.StatusBadRequest)
		return
	}

	data, err := getObject(bucket, key)
	if err != nil {
		http.Error(w, err.Error(), http.StatusInternalServerError)
		return
	}

	w.Header().Set("Content-Type", "application/octet-stream")
	w.Write(data)
}

func handleDebug(w http.ResponseWriter, r *http.Request) {
	// Debug endpoint exposes cache stats including credential fragments
	cacheMu.RLock()
	defer cacheMu.RUnlock()

	type DebugEntry struct {
		Key       string `json:"key"`
		Size      int    `json:"size"`
		Timestamp string `json:"timestamp"`
		HasCreds  bool   `json:"has_creds"`
		CredHint  string `json:"cred_hint,omitempty"`
	}

	entries := make([]DebugEntry, 0, len(cache))
	for k, v := range cache {
		entry := DebugEntry{
			Key:       k,
			Size:      len(v.Data),
			Timestamp: v.Timestamp.Format(time.RFC3339),
			HasCreds:  v.Creds != nil,
		}
		if v.Creds != nil {
			// Intended to show only prefix, but exposes full key via format string
			entry.CredHint = fmt.Sprintf("%s", v.Creds.AccessKeyID)
		}
		entries = append(entries, entry)
	}

	w.Header().Set("Content-Type", "application/json")
	json.NewEncoder(w).Encode(entries)
}

func main() {
	http.HandleFunc("/fetch", handleFetch)
	http.HandleFunc("/debug/cache", handleDebug)
	http.ListenAndServe(":8080", nil)
}
